"use client"

import animation from "react-useanimations/lib/userX"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "User X" from https://useanimations.com (MIT): https://useanimations.com/icons/user-x
export function AnimatedUserX(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover"
      {...props}
    />
  )
}
